assert relations.rank() == 33
assert pairing.dimensions() == (77, 56)
assert pairing.rank() == 43
assert (relations * pairing).is_zero()

print("FZ quotient dimension:", 77 - relations.rank())
print("Intersection-pairing rank:", pairing.rank())
